print('  first 256 bytes:', blob[:256].hex())
print('  ascii:', "".join(chr(b) if 32<=b<127 else "." for b in blob[:256]))
# does the mediadb FrameInfo FrameKey match DataKey in -1?
ck = con(mdb).execute('select FrameKey from FrameInfo limit 3').fetchall()
print('  mediadb FrameKeys sample:', [show(k[0], 16) for k in ck])
print('  -1 DataKeys sample:', [show(s[0], 16) for s in sizes[:3]])
